import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.OutputStream;
import java.io.PrintStream;
import java.util.HashSet;
import java.util.Set;

/**
 * System logger.
 *
 * Output:
 *
 * log/
 * ├── log.txt
 * ├── Worker_1.txt
 * ├── Worker_2.txt
 * ├── Worker_3.txt
 * └── ...
 *
 * log.txt:
 *     Contains all system events.
 *
 * Worker_n.txt:
 *     Contains only events generated by Worker_n.
 */
public final class ProjectLogger {

    private final long startNanos;
    private final PrintStream out;

    /*
     * Protect all log writes because multiple threads
     * can write to the logger concurrently.
     */
    private final Object writeLock = new Object();

    /*
     * Remember which Worker log files have already
     * been initialized during this program run.
     *
     * First write:
     *     overwrite old file
     *
     * Later writes:
     *     append to the same file
     */
    private final Set<String> initializedWorkers =
            new HashSet<>();

    /**
     * Create the logger.
     *
     * The creation time is treated as simulationStart.
     */
    public ProjectLogger() {
        this(createMainLogStream());
    }

    /**
     * Constructor for a custom PrintStream.
     */
    public ProjectLogger(PrintStream out) {
        this.out = out;
        this.startNanos = System.nanoTime();
    }

    /**
     * Create the main log file.
     *
     * The old log.txt is cleared when the program starts.
     */
    private static PrintStream createMainLogStream() {

        try {

            // Create log directory.
            File logDirectory = new File("log");

            if (!logDirectory.exists()
                    && !logDirectory.mkdirs()) {

                throw new RuntimeException(
                        "Cannot create log directory"
                );
            }

            // Main log file.
            File logFile =
                    new File(logDirectory, "log.txt");

            /*
             * false = overwrite old log.
             *
             * Each execution starts with a clean log.txt.
             */
            FileOutputStream fileOut =
                    new FileOutputStream(
                            logFile,
                            false
                    );

            /*
             * Write to both:
             *
             * 1. Console
             * 2. log/log.txt
             */
            return new PrintStream(
                    new OutputStream() {

                        @Override
                        public void write(int b)
                                throws java.io.IOException {

                            System.out.write(b);
                            fileOut.write(b);
                        }

                        @Override
                        public void write(
                                byte[] b,
                                int off,
                                int len
                        ) throws java.io.IOException {

                            System.out.write(
                                    b,
                                    off,
                                    len
                            );

                            fileOut.write(
                                    b,
                                    off,
                                    len
                            );
                        }

                        @Override
                        public void flush()
                                throws java.io.IOException {

                            System.out.flush();
                            fileOut.flush();
                        }

                        @Override
                        public void close()
                                throws java.io.IOException {

                            System.out.flush();
                            fileOut.flush();
                            fileOut.close();
                        }

                    },
                    true
            );

        } catch (FileNotFoundException e) {

            throw new RuntimeException(
                    "Cannot create log/log.txt",
                    e
            );
        }
    }

    /**
     * Return elapsed time in milliseconds
     * since the logger was created.
     */
    public long now() {

        return (
                System.nanoTime()
                        - startNanos
        ) / 1_000_000L;
    }

    // ============================================================
    // System events
    // ============================================================

    public void systemStart(Config config) {

        write(
                "SYSTEM_START",
                config.describe()
        );
    }

    public void systemEvent(String detail) {

        write(
                "SYSTEM",
                detail
        );
    }

    public void systemStop(
            int completedJobs,
            int totalJobs
    ) {

        write(
                "SYSTEM_STOP",
                "completed="
                        + completedJobs
                        + "/"
                        + totalJobs
        );
    }

    // ============================================================
    // Job events
    // ============================================================

    public void jobArrived(Job job) {

        write(
                "JOB_ARRIVED",
                detailOf(job)
        );
    }

    public void jobStarted(Job job) {

        write(
                "JOB_STARTED",
                "job="
                        + job.id
                        + " priority="
                        + job.priority
        );
    }

    public void workFinished(Job job) {

        write(
                "WORK_FINISHED",
                "job="
                        + job.id
        );
    }

    public void resourceWaitStarted(Job job) {

        write(
                "RESOURCE_WAIT",
                "job="
                        + job.id
                        + " resource="
                        + job.resource
        );
    }

    public void resourceAcquired(
            Job job,
            long waitedMs
    ) {

        write(
                "RESOURCE_ACQUIRED",
                "job="
                        + job.id
                        + " resource="
                        + job.resource
                        + " waited="
                        + waitedMs
                        + "ms"
        );
    }

    public void resourceReleased(Job job) {

        write(
                "RESOURCE_RELEASED",
                "job="
                        + job.id
                        + " resource="
                        + job.resource
        );
    }

    public void jobCompleted(Job job) {

        write(
                "JOB_COMPLETED",
                "job="
                        + job.id
        );
    }

    // ============================================================
    // Monitor events
    // ============================================================

    public void monitor(
            int ready,
            int running,
            int completed,
            String resourceStatus
    ) {

        write(
                "MONITOR",
                "ready="
                        + ready
                        + " running="
                        + running
                        + " completed="
                        + completed
                        + " "
                        + resourceStatus
        );
    }

    // ============================================================
    // Internal methods
    // ============================================================

    /**
     * Create the standard Job detail.
     */
    private static String detailOf(Job job) {

        StringBuilder sb =
                new StringBuilder();

        sb.append("job=")
          .append(job.id)
          .append(" priority=")
          .append(job.priority)
          .append(" work=")
          .append(job.workMs)
          .append("ms");

        if (job.resource != ResourceType.NONE) {

            sb.append(" resource=")
              .append(job.resource)
              .append("(")
              .append(job.resourceMs)
              .append("ms)");
        }

        return sb.toString();
    }

    /**
     * Write one event.
     *
     * Every event goes to:
     *
     * 1. Console
     * 2. log/log.txt
     *
     * If the current thread is Worker_n,
     * the same line is also written to:
     *
     * log/Worker_n.txt
     */
    private void write(
            String event,
            String detail
    ) {

        String threadName =
                Thread.currentThread().getName();

        String line = String.format(
                "[%8d ms] [%-10s] %-18s %s",
                now(),
                shorten(threadName),
                event,
                detail == null
                        ? ""
                        : detail
        );

        /*
         * Synchronize the entire logging operation
         * so multiple Worker threads cannot mix
         * their output.
         */
        synchronized (writeLock) {

            // Write to console + main log.
            out.println(line);
            out.flush();

            // Write a copy to the Worker-specific log.
            writeWorkerLog(
                    threadName,
                    line
            );
        }
    }

    /**
     * Write Worker events to a separate file.
     *
     * Example:
     *
     * Worker_1 -> log/Worker_1.txt
     * Worker_2 -> log/Worker_2.txt
     */
    private void writeWorkerLog(
            String threadName,
            String line
    ) {

        /*
         * Only Worker_1, Worker_2, Worker_3, ...
         * get separate log files.
         */
        if (!threadName.matches(
                "Worker-[0-9]+"
        )) {
            return;
        }

        try {

            File logDirectory =
                    new File("log");

            if (!logDirectory.exists()
                    && !logDirectory.mkdirs()) {

                return;
            }

            File workerLogFile =
                    new File(
                            logDirectory,
                            threadName + ".txt"
                    );

            /*
             * First event:
             *     append = false
             *
             * This clears the old Worker log.
             *
             * Later events:
             *     append = true
             *
             * This keeps adding to the same run.
             */
            boolean append =
                    initializedWorkers.contains(
                            threadName
                    );

            try (PrintStream workerOut =
                         new PrintStream(
                                 new FileOutputStream(
                                         workerLogFile,
                                         append
                                 )
                         )) {

                workerOut.println(line);
                workerOut.flush();
            }

            /*
             * Mark this Worker as initialized.
             */
            initializedWorkers.add(
                    threadName
            );

        } catch (FileNotFoundException e) {

            /*
             * A problem with an individual Worker log
             * should not stop the whole scheduler.
             */
            System.err.println(
                    "Cannot create "
                            + threadName
                            + ".txt"
            );
        }
    }

    /**
     * Keep the thread name within 10 characters
     * in the main log format.
     */
    private static String shorten(
            String name
    ) {

        return name.length() <= 10
                ? name
                : name.substring(0, 10);
    }
}